    route.routeName,
    enableRedaction: globalRedactionEnabled,
    resourceLimits: resourceLimits,
  );
  final routeType = sanitizeRouteDiagnosticText(
    route.routeType,
    enableRedaction: globalRedactionEnabled,
    resourceLimits: resourceLimits,
  );
  final previousRouteName = sanitizeRouteDiagnosticName(
    previousRoute.routeName,
    enableRedaction: globalRedactionEnabled,
    resourceLimits: resourceLimits,
  );
  final previousRouteType = sanitizeRouteDiagnosticText(
    previousRoute.routeType,
    enableRedaction: globalRedactionEnabled,
    resourceLimits: resourceLimits,
  );

  buffer.writeln(
    '${type.title} | $previousRouteName ($previousRouteType) '
    '→ $routeName ($routeType)',
  );

  final arguments = sanitizeRouteDiagnosticArguments(
    route?.settings.arguments,
    enableRedaction: enableArgumentRedaction && globalRedactionEnabled,
    resourceLimits: resourceLimits,
  );
  if (arguments != null) {
    buffer.writeln(
      'Arguments: ${_routeArgumentText(arguments, resourceLimits)}',
    );
  }

  return buffer.toString().trim();
}

